import React, { useEffect, useState } from 'react';
import '../Styles/posts.sass';
import '../Styles/research-projects.sass';

// Headline projects shown under the Research prose. Star and fork counts are
// fetched live from the GitHub API; if that fails the counts are simply hidden.
const PROJECTS = [
  {
    id: 'pidsmaker',
    name: 'PIDSMaker',
    logo: process.env.PUBLIC_URL + '/courses/phishgnn/img/pidsmaker.png',
    site: 'https://ubc-provenance.github.io/PIDSMaker/',
    kicker: 'Open-source framework',
    tagline: 'Build and benchmark provenance-based intrusion detection',
    description:
      'One codebase to run, compare and extend state-of-the-art PIDSs on provenance graphs, with consistent evaluation across systems.',
    repo: 'ubc-provenance/PIDSMaker',
    tags: ['APT detection', 'Provenance graphs', 'GNNs'],
    links: [
      { href: 'https://github.com/ubc-provenance/PIDSMaker', icon: 'fa-brands fa-github', label: 'Code' },
      { href: 'https://ubc-provenance.github.io/PIDSMaker/', icon: 'fa-solid fa-book', label: 'Docs' },
      {
        href: 'https://www.usenix.org/conference/usenixsecurity25/presentation/bilot',
        icon: 'fa-solid fa-scroll',
        label: 'Paper',
      },
    ],
  },
  {
    id: 'mlx-graphs',
    name: 'mlx-graphs',
    logo: process.env.PUBLIC_URL + '/courses/phishgnn/img/mlx-graphs.svg',
    site: 'https://mlx-graphs.github.io/mlx-graphs/',
    kicker: 'Open-source library',
    tagline: 'Fast graph neural networks on Apple Silicon',
    description:
      "GPU-accelerated message passing on Apple's MLX with fused sparse kernels, behind a PyTorch Geometric-style API.",
    repo: 'mlx-graphs/mlx-graphs',
    tags: ['Apple Silicon', 'MLX', 'GNNs'],
    links: [
      { href: 'https://github.com/mlx-graphs/mlx-graphs', icon: 'fa-brands fa-github', label: 'Code' },
      { href: 'https://mlx-graphs.github.io/mlx-graphs/', icon: 'fa-solid fa-book', label: 'Docs' },
      { href: 'https://pypi.org/project/mlx-graphs/', icon: 'fa-brands fa-python', label: 'PyPI' },
    ],
  },
];

const CACHE_KEY = 'research-projects:github';
const CACHE_TTL_MS = 60 * 60 * 1000;

// Session cache keeps repeat visits off the unauthenticated rate limit
// (60 requests/hour per IP). Storage can throw in private mode; ignore it.
const readCache = () => {
  try {
    const cached = JSON.parse(sessionStorage.getItem(CACHE_KEY));
    return cached && Date.now() - cached.at < CACHE_TTL_MS ? cached.data : null;
  } catch (e) {
    return null;
  }
};

const writeCache = (data) => {
  try {
    sessionStorage.setItem(CACHE_KEY, JSON.stringify({ at: Date.now(), data }));
  } catch (e) {
    // Non-essential.
  }
};

const useGithubStats = () => {
  const [stats, setStats] = useState(readCache);

  useEffect(() => {
    if (stats) return undefined;
    let cancelled = false;

    Promise.all(
      PROJECTS.map((p) =>
        fetch(`https://api.github.com/repos/${p.repo}`, { headers: { Accept: 'application/vnd.github+json' } })
          .then((res) => (res.ok ? res.json() : null))
          .then((json) => (json ? [p.repo, { stars: json.stargazers_count, forks: json.forks_count }] : null))
          .catch(() => null)
      )
    ).then((entries) => {
      const data = Object.fromEntries(entries.filter(Boolean));
      if (cancelled || !Object.keys(data).length) return;
      writeCache(data);
      setStats(data);
    });

    return () => {
      cancelled = true;
    };
  }, [stats]);

  return stats || {};
};

const formatCount = (n) => (n >= 1000 ? `${(n / 1000).toFixed(n >= 10000 ? 0 : 1).replace(/\.0$/, '')}k` : String(n));

// Inline SVGs, not Font Awesome <i>s: these appear after the fetch resolves,
// and Font Awesome swapping <i> nodes behind React's back breaks re-renders.
const StarIcon = () => (
  <svg viewBox="0 0 16 16" width="13" height="13" fill="currentColor" aria-hidden="true" focusable="false">
    <path d="M8 .75l2.2 4.46 4.92.72-3.56 3.47.84 4.9L8 12.0l-4.4 2.3.84-4.9L.88 5.93l4.92-.72L8 .75z" />
  </svg>
);

const ForkIcon = () => (
  <svg
    viewBox="0 0 16 16"
    width="13"
    height="13"
    fill="none"
    stroke="currentColor"
    strokeWidth="1.6"
    strokeLinecap="round"
    aria-hidden="true"
    focusable="false"
  >
    <circle cx="4" cy="3" r="1.6" />
    <circle cx="12" cy="3" r="1.6" />
    <circle cx="8" cy="13" r="1.6" />
    <path d="M4 4.6v1.2c0 1.2.9 2.2 2.2 2.2h3.6c1.3 0 2.2-1 2.2-2.2V4.6M8 8v3.4" />
  </svg>
);

const ProjectCard = ({ project, github }) => (
  <article className={`research-card research-card--${project.id} card-surface`}>
    <a
      className="research-card__plate"
      href={project.site}
      target="_blank"
      rel="noopener noreferrer"
      aria-label={`${project.name} website`}
    >
      <img src={project.logo} alt={project.name} loading="lazy" />
    </a>

    <div className="research-card__body">
      <div className="research-card__meta">
        <p className="research-card__kicker">{project.kicker}</p>
        <a
          className="research-card__github"
          href={`https://github.com/${project.repo}`}
          target="_blank"
          rel="noopener noreferrer"
          aria-hidden={github ? undefined : 'true'}
          tabIndex={github ? undefined : -1}
        >
          {github && (
            <>
              <span title="GitHub stars">
                <StarIcon />
                {formatCount(github.stars)}
                <span className="visually-hidden"> stars</span>
              </span>
              <span title="GitHub forks">
                <ForkIcon />
                {formatCount(github.forks)}
                <span className="visually-hidden"> forks</span>
              </span>
            </>
          )}
        </a>
      </div>
      <h3 className="research-card__tagline">{project.tagline}</h3>
      <p className="research-card__description">{project.description}</p>

      <ul className="research-card__tags" aria-label="Topics">
        {project.tags.map((tag) => (
          <li key={tag}>{tag}</li>
        ))}
      </ul>

      <div className="research-card__links">
        {project.links.map((link) => (
          <a key={link.label} href={link.href} target="_blank" rel="noopener noreferrer">
            <i className={link.icon} aria-hidden="true" />
            {link.label}
          </a>
        ))}
      </div>
    </div>
  </article>
);

const ResearchProjects = () => {
  const github = useGithubStats();

  return (
    <div className="research-projects">
      <h3 className="post-series__title animatable fadeInUp">Main projects</h3>
      <div className="research-projects__grid animatable fadeInUp">
        {PROJECTS.map((project) => (
          <ProjectCard key={project.id} project={project} github={github[project.repo]} />
        ))}
      </div>
    </div>
  );
};

export default ResearchProjects;
